package co.edu.cinematch.core.model;
import java.time.*;
public class Funcion implements Identifiable { private String id,peliculaId,salaId,tipoFuncion,formato,estado="PROGRAMADA"; private LocalDate fechaFuncion; private LocalTime horaInicio,horaFin; private double precio; public Funcion(){} public Funcion(String peliculaId,String salaId,String tipoFuncion,LocalDate fecha,LocalTime inicio,LocalTime fin,double precio,String formato){this.peliculaId=peliculaId;this.salaId=salaId;this.tipoFuncion=tipoFuncion;fechaFuncion=fecha;horaInicio=inicio;horaFin=fin;this.precio=precio;this.formato=formato;} public String getId(){return id;}public void setId(String v){id=v;}public String getPeliculaId(){return peliculaId;}public void setPeliculaId(String v){peliculaId=v;}public String getSalaId(){return salaId;}public void setSalaId(String v){salaId=v;}public String getTipoFuncion(){return tipoFuncion;}public void setTipoFuncion(String v){tipoFuncion=v;}public LocalDate getFechaFuncion(){return fechaFuncion;}public void setFechaFuncion(LocalDate v){fechaFuncion=v;}public LocalTime getHoraInicio(){return horaInicio;}public void setHoraInicio(LocalTime v){horaInicio=v;}public LocalTime getHoraFin(){return horaFin;}public void setHoraFin(LocalTime v){horaFin=v;}public double getPrecio(){return precio;}public void setPrecio(double v){precio=v;}public String getFormato(){return formato;}public void setFormato(String v){formato=v;}public String getEstado(){return estado;}public void setEstado(String v){estado=v;} }
